const item = $input.first().json;
const body = item.body || item;

let endpoint = 'http://127.0.0.1:8785/api/v1/diagnose-incident';
let payload = body;

if (body.message || body.prompt || body.chat) {
  endpoint = 'http://127.0.0.1:8785/api/v1/chat';
  payload = {
    persona: body.persona || 'SentinelSRE',
    message: body.message || body.prompt || body.chat,
    session_id: body.session_id || 'n8n_interactive_session'
  };
} else if (body.edge_query || body.inspect_edge) {
  endpoint = 'http://127.0.0.1:8785/api/v1/edge-vitals';
  payload = {};
} else {
  endpoint = 'http://127.0.0.1:8785/api/v1/diagnose-incident';
  payload = body.payload || body;
}

return [{
  json: {
    target_endpoint: endpoint,
    forward_payload: payload,
    is_chat: endpoint.endsWith('/chat'),
    is_edge_poll: endpoint.endsWith('/edge-vitals')
  }
}];

const item = $input.first().json;
const res = item.body || item;
let audit_event = null;

if (res.diagnosis) {
  const d = res.diagnosis;
  audit_event = {
    event_type: d.severity === 'OPTIMAL' ? 'ai_sre_telemetry_verified' : 'ai_sre_remediation_directive',
    source: 'sol-002-avatar-agents',
    payload: {
      incident_id: d.incident_id,
      target_node: d.target_node,
      severity: d.severity,
      persona_responder: d.persona_responder,
      root_cause: d.root_cause,
      remediation_directives: d.remediation_directives,
      sre_playbook_ref: d.sre_playbook_ref
    }
  };
} else if (res.ai_diagnosis) {
  const d = res.ai_diagnosis;
  audit_event = {
    event_type: d.severity === 'OPTIMAL' ? 'ai_sre_edge_vitals_verified' : 'ai_sre_edge_anomaly_detected',
    source: 'sol-002-avatar-agents',
    payload: {
      incident_id: d.incident_id,
      target_node: d.target_node,
      severity: d.severity,
      persona_responder: d.persona_responder,
      root_cause: d.root_cause,
      remediation_directives: d.remediation_directives
    }
  };
} else if (res.turn) {
  audit_event = {
    event_type: 'ai_persona_dialogue',
    source: 'sol-002-avatar-agents',
    payload: {
      persona: res.turn.persona,
      role: res.turn.role,
      turn_count: res.turn.turn_count,
      session_id: res.turn.session_id
    }
  };
} else {
  audit_event = {
    event_type: 'ai_avatar_execution',
    source: 'sol-002-avatar-agents',
    payload: res
  };
}

return [{
  json: {
    status: 'SUCCESS',
    result: res,
    audit_event: audit_event
  }
}];
